UPDATE teacher 
set xb = #{xb},school = #{school},career = #{career},title = #{title},teach = #{teach},csrq = #{csrq},
achievement = #{achievement},direction = #{direction},office = #{office},phone = #{phone},degree = #{degree},picture = #{picture}
,email = #{email},phone2 = #{phone2},researchAbstract = #{researchAbstract}
WHERE tno =  #{tno}

UPDATE student SET ActualQuestions = #{ActualQuestions},Type = #{Type},
ResearchType=#{ResearchType},InsideORoutside = #{InsideORoutside}
WHERE sno =  #{sno}

